// Normalizes incoming email payload from either Gmail Trigger or Manual Test
const item = $input.first().json;

// Sample fallback data if testing manually
const from = item.from || item.sender || "John Doe <john.doe@clientcorp.io>";
const subject = item.subject || "Urgent: Project Scope Update & Next Steps";
const threadId = item.threadId || item.id || "thread_sample_12345";
let snippet = item.snippet || item.text || item.body || "Hi Lencho, we loved the automation demo you shared. We would like to expand the scope to include automated invoice reconciliation. Could you let us know your availability for a call this Thursday at 2 PM UTC to finalize the contract?";

// Clean and truncate body if needed (protect token budget)
const cleanBody = snippet.replace(/<[^>]*>?/gm, '').slice(0, 3000);

return [{
  json: {
    from,
    subject,
    threadId,
    body: cleanBody,
    receivedAt: item.date || new Date().toISOString()
  }
}];

