const response = $input.first().json;
const emailMeta = $("Pre-process & Sanitize Email").first().json;

let aiOutput = {};
try {
  const content = response.choices[0].message.content;
  aiOutput = typeof content === 'string' ? JSON.parse(content) : content;
} catch (err) {
  aiOutput = {
    category: 'Urgent Inquiry',
    urgency_score: 3,
    summary: 'Could not parse JSON response from AI Gateway.',
    action_needed: 'Check email manually.',
    draft_reply: 'Hi, thank you for reaching out. I received your message and will get back to you shortly.'
  };
}

// Determine emoji badge based on urgency
const urgencyBadge = '⚡'.repeat(Math.min(aiOutput.urgency_score || 1, 5));

// Format telegram markdown message
const telegramText = `📬 *New Inbound Email Analyzed*\n` +
`*From:* \`${emailMeta.from}\`\n` +
`*Subject:* *${emailMeta.subject}*\n` +
`*Category:* ${aiOutput.category} (${urgencyBadge})\n\n` +
`📋 *Executive Summary:*\n${aiOutput.summary}\n\n` +
`🎯 *Action Needed:*\n${aiOutput.action_needed}\n\n` +
`✍️ *Suggested Draft Reply:*\n\"_${aiOutput.draft_reply}_\"`;

return [{
  json: {
    ...emailMeta,
    ai: aiOutput,
    telegramText,
    sendCallback: `send:${emailMeta.threadId.slice(0, 40)}`,
    archiveCallback: `arch:${emailMeta.threadId.slice(0, 40)}`
  }
}];

const query = $input.first().json.callback_query;
const data = query.data || '';
const parts = data.split(':');
const action = parts[0];
const threadId = parts.slice(1).join(':');
const messageId = query.message.message_id;
const chatId = query.message.chat.id;
const queryId = query.id;

return [{
  json: {
    action,
    threadId,
    messageId,
    chatId,
    queryId,
    originalText: query.message.text,
    timestamp: new Date().toLocaleTimeString()
  }
}];

